// ESP32 — 28BYJ-48 Schrittmotor mit ULN2003
#include <Stepper.h>

// 2048 Schritte pro Umdrehung (Full-Step)
const int STEPS_PER_REV = 2048;

// Achtung: Reihenfolge IN1, IN3, IN2, IN4 — nicht IN1-4 der Reihe nach!
Stepper myStepper(STEPS_PER_REV, 19, 5, 18, 17);

void setup() {
  Serial.begin(115200);
  myStepper.setSpeed(10);  // ca. 10 U/min — ruhig und zuverlässig
  Serial.println("Stepper bereit.");
}

void loop() {
  Serial.println("90 Grad vorwaerts");
  myStepper.step(512);    // 512 Schritte = 90 Grad
  delay(1000);

  Serial.println("90 Grad zurueck");
  myStepper.step(-512);   // negatives Vorzeichen = Rueckwaerts
  delay(1000);
}
